SET ROLE talus_fn;
CREATE OR REPLACE FUNCTION app.create_booking(p_customer_id uuid,p_category_location_id uuid,p_start_time timestamptz,p_end_time timestamptz) RETURNS TABLE(booking_id uuid,booking_item_id uuid,booking_terms_revision_id uuid,item_terms_revision_id uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,public AS $$ DECLARE t uuid:=app.current_context_tenant_id();b uuid:=gen_random_uuid();i uuid:=gen_random_uuid();bt uuid:=gen_random_uuid();it uuid:=gen_random_uuid();l uuid;BEGIN PERFORM app.require_staff_role('staff');IF p_end_time<=p_start_time OR NOT EXISTS(SELECT 1 FROM app.customer WHERE tenant_id=t AND customer_id=p_customer_id) THEN RAISE EXCEPTION 'BOOKING_INPUT_INVALID' USING ERRCODE='P0001';END IF;SELECT location_id INTO l FROM app.category_location WHERE tenant_id=t AND category_location_id=p_category_location_id;IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND' USING ERRCODE='P0001';END IF;INSERT INTO app.booking(tenant_id,booking_id,booking_reference,pickup_location_id,return_location_id,state) VALUES(t,b,'API-'||substr(b::text,1,8),l,l,'draft');INSERT INTO app.booking_terms_revision(tenant_id,booking_terms_revision_id,booking_id,revision_number) VALUES(t,bt,b,1);INSERT INTO app.booking_item(tenant_id,booking_item_id,booking_id,item_number,state) VALUES(t,i,b,1,'reserved');INSERT INTO app.booking_item_terms_revision(tenant_id,booking_item_terms_revision_id,booking_item_id,booking_id,booking_terms_revision_id,category_location_id,revision_number,scheduled_start_at,scheduled_end_at,chargeable_day_count) VALUES(t,it,i,b,bt,p_category_location_id,1,p_start_time,p_end_time,GREATEST(1,(p_end_time::date-p_start_time::date)));UPDATE app.booking_item SET current_terms_revision_id=it WHERE tenant_id=t AND booking_item_id=i;PERFORM app.append_audit('booking.created','booking',b);RETURN QUERY SELECT b,i,bt,it;END;$$;
REVOKE ALL ON FUNCTION app.create_booking(uuid,uuid,timestamptz,timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.create_booking(uuid,uuid,timestamptz,timestamptz) TO talus_staff,talus_api;
RESET ROLE;
